#!/usr/bin/env python3
from pathlib import Path
import base64, gzip
FILES = {
    'assets/api.css': '',
    'scripts/validate_mi_extensions.js': '',
    '.github/workflows/validate.yml': '',
}
for path, payload in FILES.items():
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(gzip.decompress(base64.b64decode(payload)))
for obsolete in [
    "scripts/apply_mi_ui_a.py",
    "scripts/apply_mi_ui_b.py",
    "scripts/apply_mi_ui_c.py",
    "scripts/apply_mi_stages_1_2.py",
    "scripts/.mi_api_payload.txt",
]:
    Path(obsolete).unlink(missing_ok=True)
print("Applied MI UI styles, tests and final workflow")
